steps.codeExample:
use axum::{routing::post, Json, Router};
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize)]
struct NovoUsuario {
    nome: String,
}

async fn criar_usuario(Json(payload): Json<NovoUsuario>) -> Json<NovoUsuario> {
    Json(payload)
}

#[tokio::main]
async fn main() {
    let app: Router = Router::new().route("/users", post(criar_usuario));
}

